import argparse
from collections import Counter
import hashlib
import json
from pathlib import Path
import subprocess
import xml.etree.ElementTree as ET


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def suite(path):
    tree = ET.parse(path)
    summary = tree.find("testsuite")
    counts = {key: int(summary.get(key, "0")) for key in ("tests", "failures", "errors", "skipped")}
    counts["passed"] = counts["tests"] - sum(counts[key] for key in ("failures", "errors", "skipped"))
    issues = [{"class": case.get("classname"), "test": case.get("name"),
               "outcome": issue.tag, "message": issue.get("message", "")}
              for case in tree.iter("testcase") for issue in case
              if issue.tag in ("failure", "error", "skipped")]
    return {"path": str(path), "sha256": digest(path), "counts": counts,
            "seconds": float(summary.get("time")), "issues": issues}


def classification(issue):
    name = issue["class"]
    message = issue["message"]
    if name.startswith("tests.integration.test_") and "imq-umat-recovery" in message:
        return "hardcoded producer sibling in RA fixtures/reproducer"
    if name == "tests.test_workbench_browser":
        return "missing compatible Chromium prerequisite"
    if name == "tests.test_a_source_that_does_not_compile_is_not_a_run_that_failed":
        return "missing explicit Intel compiler environment"
    if name == "tests.test_repository_standards":
        return "documentation links" if "documented_commands" in issue["test"] else "machine paths in live docs and historical transcripts"
    if name == "tests.test_source_discovery":
        return "missing historical jgomezc1 originals; directory-only prerequisite was insufficient"
    raise AssertionError(f"unclassified original failure: {issue}")


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--ra", type=Path, required=True)
    parser.add_argument("--umat", type=Path, required=True)
    args = parser.parse_args()
    work = Path(__file__).resolve().parent
    baseline = json.loads((args.ra / "docs/evidence/recovery_clean_clone.json").read_text())
    original = []
    for name, run in baseline["offline_suites"].items():
        for issue in run["issues"]:
            if issue["outcome"] in ("failure", "error"):
                original.append({"run": name, "class": issue["class"], "test": issue["test"],
                                 "outcome": issue["outcome"], "classification": classification(issue),
                                 "message": issue["message"].splitlines()[0]})
    final = {name: suite(work / f"{name}_offline_final.xml") for name in ("ra", "umat")}
    assert all(run["counts"]["failures"] == run["counts"]["errors"] == 0 for run in final.values())
    gate = json.loads((work / "installed-final/report.json").read_text())
    assert gate["passed"]
    examples = {name: json.loads((work / f"example-evidence/{name}/usage_examples.json").read_text())
                for name in ("RA", "UMAT")}
    for report in examples.values():
        report.pop("previous_failures", None)
        assert all(command["returncode"] == 0 for command in report["commands"])
    browser = json.loads((work / "browser-demo-verified/report.json").read_text())
    assert browser["passed"] and browser["server_stopped"] and browser["cli_returncode"] == 0
    from umat_oti.store import transform_fingerprint
    assert transform_fingerprint() == "6aa20d22e37f14c9"
    payload = {
        "schema": "recovery_portability_v1", "date": "2026-09-18",
        "scope": "working-tree portability slice, not committed clean-clone or full historical corpus acceptance",
        "bounded_slice_passed": True, "committed_clean_clone_proven": False,
        "full_historical_corpus_complete": False, "new_abaqus_jobs": 0,
        "work": str(work), "original_failure_classifications": original,
        "original_classification_counts": dict(Counter(row["classification"] for row in original)),
        "baseline_report_sha256": digest(args.ra / "docs/evidence/recovery_clean_clone.json"),
        "final_offline_suites": final, "umat_deselected": 5,
        "intermediate_suites": {name: suite(work / f"{name}_offline.xml") for name in ("ra", "umat")},
        "installed_gate": gate, "installed_examples": examples, "installed_browser_demo": browser,
        "presentation_consume": json.loads((work / "installed-final/analytic_checks.json").read_text()),
        "fingerprint_before": "6aa20d22e37f14c9", "fingerprint_after": transform_fingerprint(),
        "generation_lock_and_fixture_bytes_changed": False,
        "wheels": [{"name": path.name, "sha256": digest(path)} for path in sorted((work / "installed-final/wheels").glob("*.whl"))],
        "source_status": {name: subprocess.check_output(["git", "-C", str(repo), "status", "--short"], text=True)
                          for name, repo in (("RA", args.ra), ("UMAT", args.umat))},
        "validation_harnesses": {path.name: {"sha256": digest(path), "source": path.read_text()}
                                 for path in (work / "check_installed_demo.py", Path(__file__))},
        "raw_artifacts": [{"path": str(path.relative_to(work)), "sha256": digest(path)}
                          for pattern in ("*.xml", "*.log", "browser-demo-verified/*.png", "browser-demo-verified/*.log")
                          for path in sorted(work.glob(pattern))],
        "execution_notes": [
            "All ten examples executed sequentially using isolated installed imports in a new empty environment.",
            "The second UMAT full-suite command was requested sync but auto-backgrounded after redirected-output idle; later presentation/browser probes overlapped it. No two full suites or example cases ran concurrently.",
            "The first snapshot copied a submodule .git pointer; only that temporary copied pointer was removed before the successful new-work gate retry.",
            "The first new-environment RA run failed genuine OTILib import because SciPy was absent; installing the declared external dependency resolved all 16 failures without gate changes.",
            "One browser harness CLI probe omitted --config; corrected and rerun successfully, with all owned servers stopped.",
            "Source snapshots contain explicit uncommitted overlays and one already documented permissive submodule; no external historical corpus was copied.",
        ],
    }
    encoded = json.dumps(payload, indent=2) + "\n"
    for repo in (args.ra, args.umat):
        (repo / "docs/evidence/recovery_portability.json").write_text(encoded)
    print(json.dumps({"suites": {key: value["counts"] for key, value in final.items()},
                      "original_failure_entries": len(original), "wheels": payload["wheels"]}, indent=2))


if __name__ == "__main__":
    main()
